mapper.select:
SELECT count(*)
FROM reservation r
JOIN reservation_time rt ON r.id = rt.reservation_id
WHERE r.status IN ('RESERVED', 'CHARGING')
AND r.charger_id = #{chargerId} 

    AND rt.start_time < #{endTime}
    AND rt.end_time > #{startTime}

SELECT 
    DATE_FORMAT(rt.start_time, '%Y-%m-%d %H:%i:%s') AS startTime,
    DATE_FORMAT(rt.end_time, '%Y-%m-%d %H:%i:%s') AS endTime
FROM reservation r
JOIN reservation_time rt ON r.id = rt.reservation_id
WHERE DATE(rt.start_time) = #{date}
  AND r.status IN ('RESERVED', 'CHARGING')


          AND r.charger_id = #{chargerId}


          AND r.station_id = #{stationId}

/* ReservationMapper.getSigunguList : 선택된 시/도에 종속된 시/군/구 추출 */
SELECT DISTINCT city 
FROM station 
WHERE metro = #{metro} 
  AND city IS NOT NULL AND city != '' 
ORDER BY city ASC

/* ReservationMapper.getStationList : 동적 필터링이 적용된 충전소 리스트 조회 */ SELECT id, name, address, metro, city, rapid_cnt AS rapidCnt, slow_cnt AS slowCnt, car_type AS carType, latitude, longitude FROM station
AND metro = #{metro}
AND city = #{city}
AND rapid_cnt > 0
AND slow_cnt > 0
ORDER BY name ASC

